cd D:/applications/habit-tracker && cat > .aidd/tmp-restore.ts <<'EOF'
import { Database } from 'bun:sqlite';
const db = new Database('data/habit-tracker.db');
const before = db.query('SELECT count(*) as c FROM habits WHERE archived_at IS NOT NULL').get() as { c: number };
db.run('UPDATE habits SET archived_at = NULL WHERE id LIKE ?', ['seed-habit-%']);
const after = db.query('SELECT count(*) as c FROM habits WHERE archived_at IS NULL').get() as { c: number };
console.log('archived before restore:', before.c, '| non-archived after restore:', after.c);
db.close();
EOF
bun run .aidd/tmp-restore.ts
